TYPE Nom_type_enregistrement = ENREGISTREMENT

  Champ1 : Type1 ;

  Champ2 : Type2 ;

  ...

  ChampN : TypeN ;

FIN ;


VAR nom_fichier : FICHIER DE Nom_type_enregistrement ;

TYPE eleve = ENREGISTREMENT

  Nom : Chaîne de caractères ;

  Age : Entier ;

FIN ;


VAR Fichier_eleves : FICHIER DE eleve ;

ALGORITHME Fichier_ecriture ;

TYPE eleve = ENREGISTREMENT

  Nom : Chaîne de caractères ;

  Age : Entier ;

FIN ;

VAR

  Fichier_eleves : FICHIER DE eleve ;

  Enreg : eleve ;

  Choix : Entier ;

DÉBUT

  {Création du fichier « Fichier_élèves » : ouverture en écriture}

  ASSOCIER(Fichier_eleves, "D:\TP\MonFichier.dat") ;

  REECRIRE(Fichier_eleves) ;

  RÉPÉTER

    ÉCRIRE('Nom de l'élève ? ') ;

    LIRE(Enreg.Nom) ;

    ÉCRIRE('Age de l'élève ? ') ;

    LIRE(Enreg.Age) ;

    {On écrit sur le fichier}

    ÉCRIRE(Fichier_eleves, Enreg) ;

    ÉCRIRE('Autre saisie ? 1. OUI 2. NON') ;

    LIRE(Choix) ;

  JUSQU'À (Choix = 2) ;

  FERMER(Fichier_eleves) ;

FIN.

ALGORITHME Fichier_lecture ;

TYPE eleve = ENREGISTREMENT

  Nom : Chaîne de caractères ;

  Age : Entier ;

FIN ;

VAR

  Fichier_eleves : FICHIER DE eleve ;

  Enreg : eleve ;

DÉBUT

  {Consultation du fichier « Fichier_élèves » : ouverture en lecture}

  ASSOCIER(Fichier_eleves, "D:\TP\MonFichier.dat") ;

  RELIRE(Fichier_eleves) ;

  TANT QUE (NON FDF(Fichier_eleves)) FAIRE

    LIRE(Fichier_eleves, Enreg) ; {On lit dans le fichier}

    ÉCRIRE(Enreg.Nom, '  ', Enreg.Age) ;

  FIN TANT QUE ;

  FERMER(Fichier_eleves) ;

FIN.

ALGORITHME Lecture_texte ;

VAR

  F : TEXTE ;

  S : Chaîne de caractères ;

DÉBUT

  ASSOCIER(F, "D:\TP\MonFichier.txt") ;

  RELIRE(F) ;

  TANT QUE (NON FDF(F)) FAIRE

    LIRE(F, S); {Lire une ligne complète dans « F »}

    ÉCRIRE(S); {Écrire « S » sur l'écran}

  FIN TANT QUE ;

  FERMER(F) ;

FIN.
